package com.tradingplatform.controller;
import com.tradingplatform.decision.*; import com.tradingplatform.market.*; import com.tradingplatform.paper.PaperTradingEngine; import java.math.BigDecimal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/opportunities") public class DecisionController { private final DecisionEngine decisions; private final MarketDataService market; private final PaperTradingEngine paper; public DecisionController(DecisionEngine d,MarketDataService m,PaperTradingEngine p){decisions=d;market=m;paper=p;} @GetMapping("/{symbol}") public Decision decision(@PathVariable String symbol,@RequestParam(defaultValue="1D")String timeframe){Timeframe t=Timeframe.parse(timeframe);var candles=t.supportsIntraday()?market.intraday(symbol,t):market.history(symbol,t,java.time.LocalDate.now().minusYears(2),java.time.LocalDate.now());return decisions.evaluate(symbol,t,candles,paper.account().availableCash());} }
